import type { SVGProps } from "react";
import { cn } from "@/lib/utils";

interface DockeeperLogoProps extends Omit<SVGProps<SVGSVGElement>, "children"> {
	size?: number;
	hueRotate?: number;
	saturate?: number;
	brightness?: number;
	contrast?: number;
	opacity?: number;
}

const LOGO_BASE64 =
	"";

export function DockeeperLogo({
	size = 32,
	className,
	hueRotate = 290,
	saturate = 1.45,
	brightness = 0.98,
	contrast = 1.08,
	opacity = 1,
	style,
	...props
}: DockeeperLogoProps) {
	const filter = `hue-rotate(${hueRotate}deg) saturate(${saturate}) brightness(${brightness}) contrast(${contrast})`;

	return (
		<svg
			xmlns="http://www.w3.org/2000/svg"
			viewBox="0 0 120 120"
			width={size}
			height={size}
			role="img"
			aria-label="Dockeeper"
			className={cn("shrink-0", className)}
			style={style}
			{...props}
		>
			<image
				href={`data:image/svg+xml;base64,${LOGO_BASE64}`}
				x="0"
				y="0"
				width="120"
				height="120"
				preserveAspectRatio="xMidYMid meet"
				style={{ filter, opacity }}
			/>
		</svg>
	);
}
